-- Generated by `python -m elt render` from snowflake/pipeline.yml. Do not edit by hand.
USE DATABASE LOANS;

-- Suspend the graph while it is (re)defined; children must be resumed before the root.
ALTER TASK IF EXISTS CORE.T_REJECT_EVENTS SUSPEND;

CREATE STREAM IF NOT EXISTS RAW.RAW_LOAN_EVENTS_STREAM ON TABLE RAW.RAW_LOAN_EVENTS APPEND_ONLY = TRUE;
CREATE STREAM IF NOT EXISTS RAW.RAW_LOAN_EVENTS_DQ_STREAM ON TABLE RAW.RAW_LOAN_EVENTS APPEND_ONLY = TRUE;
CREATE STREAM IF NOT EXISTS RAW.RAW_PAYMENTS_STREAM ON TABLE RAW.RAW_PAYMENTS APPEND_ONLY = TRUE;
CREATE STREAM IF NOT EXISTS RAW.RAW_PAYMENTS_DQ_STREAM ON TABLE RAW.RAW_PAYMENTS APPEND_ONLY = TRUE;
CREATE STREAM IF NOT EXISTS CORE.LOAN_ACCOUNTS_STREAM ON TABLE CORE.LOAN_ACCOUNTS;
CREATE STREAM IF NOT EXISTS CORE.PAYMENTS_STREAM ON TABLE CORE.PAYMENTS APPEND_ONLY = TRUE;

CREATE OR REPLACE TASK CORE.T_REJECT_EVENTS
  USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
  USER_TASK_TIMEOUT_MS = 600000
  SCHEDULE = 'USING CRON */5 * * * * UTC'
  SUSPEND_TASK_AFTER_NUM_FAILURES = 3
  WHEN SYSTEM$STREAM_HAS_DATA('RAW.RAW_LOAN_EVENTS_STREAM') OR SYSTEM$STREAM_HAS_DATA('RAW.RAW_PAYMENTS_STREAM') OR SYSTEM$STREAM_HAS_DATA('CORE.LOAN_ACCOUNTS_STREAM') OR SYSTEM$STREAM_HAS_DATA('CORE.PAYMENTS_STREAM')
AS
-- Root task body: quarantine raw rows that fail validation.
-- Reads the *_DQ streams, which are separate from the streams the load tasks consume,
-- so rejecting a row never moves the load tasks' offsets.
INSERT INTO CORE.REJECTED_EVENTS (source, payload, file_name, reason, rejected_at)
SELECT source, payload, file_name, reason, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ
FROM (
  SELECT
    'loan_events' AS source,
    payload,
    file_name,
    CASE
      WHEN payload:loan_id::STRING IS NULL THEN 'missing loan_id'
      WHEN payload:customer_id::STRING IS NULL THEN 'missing customer_id'
      WHEN TRY_TO_TIMESTAMP_NTZ(payload:event_ts::STRING) IS NULL THEN 'invalid event_ts'
      WHEN TRY_TO_DECIMAL(payload:balance::STRING, 12, 2) IS NULL THEN 'invalid balance'
      WHEN TRY_TO_DECIMAL(payload:balance::STRING, 12, 2) < 0 THEN 'negative balance'
    END AS reason
  FROM RAW.RAW_LOAN_EVENTS_DQ_STREAM
  UNION ALL
  SELECT
    'payments' AS source,
    payload,
    file_name,
    CASE
      WHEN payload:payment_id::STRING IS NULL THEN 'missing payment_id'
      WHEN payload:loan_id::STRING IS NULL THEN 'missing loan_id'
      WHEN TRY_TO_DECIMAL(payload:amount::STRING, 12, 2) IS NULL THEN 'invalid amount'
      WHEN TRY_TO_DECIMAL(payload:amount::STRING, 12, 2) <= 0 THEN 'non-positive amount'
      WHEN TRY_TO_DATE(payload:due_date::STRING) IS NULL THEN 'invalid due_date'
      WHEN TRY_TO_DATE(payload:paid_date::STRING) IS NULL THEN 'invalid paid_date'
    END AS reason
  FROM RAW.RAW_PAYMENTS_DQ_STREAM
)
WHERE reason IS NOT NULL;

CREATE OR REPLACE TASK CORE.T_LOAD_ACCOUNTS
  USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
  USER_TASK_TIMEOUT_MS = 600000
  AFTER CORE.T_REJECT_EVENTS
AS
-- Upsert the latest image of each loan from new raw events.
--  * several events for one loan in a batch: keep the newest (QUALIFY)
--  * an event older than what is already stored (late or replayed): ignored
--  * invalid rows: skipped here, quarantined by the root task
MERGE INTO CORE.LOAN_ACCOUNTS t
USING (
  SELECT
    loan_id, customer_id, state, principal, balance, apr, status, is_closed, event_ts,
    SHA2(CONCAT_WS('|', customer_id, COALESCE(state, ''), COALESCE(CAST(balance AS STRING), ''),
                   COALESCE(CAST(apr AS STRING), ''), COALESCE(status, ''), CAST(is_closed AS STRING)), 256) AS hashdiff
  FROM (
    SELECT
      payload:loan_id::STRING                               AS loan_id,
      payload:customer_id::STRING                           AS customer_id,
      payload:state::STRING                                 AS state,
      TRY_TO_DECIMAL(payload:principal::STRING, 12, 2)      AS principal,
      TRY_TO_DECIMAL(payload:balance::STRING, 12, 2)        AS balance,
      TRY_TO_DECIMAL(payload:apr::STRING, 6, 4)             AS apr,
      UPPER(TRIM(payload:status::STRING))                   AS status,
      COALESCE(payload:event_type::STRING = 'closed', FALSE) AS is_closed,
      TRY_TO_TIMESTAMP_NTZ(payload:event_ts::STRING)        AS event_ts
    FROM RAW.RAW_LOAN_EVENTS_STREAM
  )
  WHERE loan_id IS NOT NULL AND customer_id IS NOT NULL AND event_ts IS NOT NULL
    AND balance IS NOT NULL AND balance >= 0
  QUALIFY ROW_NUMBER() OVER (PARTITION BY loan_id ORDER BY event_ts DESC) = 1
) s
ON t.loan_id = s.loan_id
WHEN MATCHED AND s.event_ts > t.event_ts THEN UPDATE SET
  customer_id = s.customer_id,
  state       = s.state,
  principal   = COALESCE(s.principal, t.principal),
  balance     = s.balance,
  apr         = s.apr,
  status      = s.status,
  is_closed   = s.is_closed,
  event_ts    = s.event_ts,
  hashdiff    = s.hashdiff,
  updated_at  = CURRENT_TIMESTAMP()::TIMESTAMP_NTZ
WHEN NOT MATCHED THEN INSERT
  (loan_id, customer_id, state, principal, balance, apr, status, is_closed, event_ts, hashdiff, updated_at)
VALUES
  (s.loan_id, s.customer_id, s.state, s.principal, s.balance, s.apr, s.status, s.is_closed, s.event_ts, s.hashdiff,
   CURRENT_TIMESTAMP()::TIMESTAMP_NTZ);

CREATE OR REPLACE TASK CORE.T_LOAD_PAYMENTS
  USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
  USER_TASK_TIMEOUT_MS = 600000
  AFTER CORE.T_REJECT_EVENTS
AS
-- Insert-only load of payments, idempotent on payment_id (re-sent payments are ignored).
MERGE INTO CORE.PAYMENTS t
USING (
  SELECT *
  FROM (
    SELECT
      payload:payment_id::STRING                       AS payment_id,
      payload:loan_id::STRING                          AS loan_id,
      TRY_TO_DECIMAL(payload:amount::STRING, 12, 2)    AS amount,
      TRY_TO_DATE(payload:due_date::STRING)            AS due_date,
      TRY_TO_DATE(payload:paid_date::STRING)           AS paid_date,
      LOWER(payload:channel::STRING)                   AS channel,
      loaded_at
    FROM RAW.RAW_PAYMENTS_STREAM
  )
  WHERE payment_id IS NOT NULL AND loan_id IS NOT NULL AND amount > 0
    AND due_date IS NOT NULL AND paid_date IS NOT NULL
  QUALIFY ROW_NUMBER() OVER (PARTITION BY payment_id ORDER BY loaded_at) = 1
) s
ON t.payment_id = s.payment_id
WHEN NOT MATCHED THEN INSERT
  (payment_id, loan_id, amount, due_date, paid_date, days_late, channel, loaded_at)
VALUES
  (s.payment_id, s.loan_id, s.amount, s.due_date, s.paid_date,
   GREATEST(DATEDIFF(day, s.due_date, s.paid_date), 0), s.channel, s.loaded_at);

CREATE OR REPLACE TASK CORE.T_LOAN_HISTORY
  USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
  USER_TASK_TIMEOUT_MS = 600000
  AFTER CORE.T_LOAD_ACCOUNTS
AS
-- SCD Type 2 in a single MERGE, driven by the standard stream on CORE.LOAN_ACCOUNTS.
-- An update shows up in the stream as a DELETE + INSERT pair; the INSERT side is the new image.
-- Each changed loan appears twice in the source:
--   merge_key = loan_id -> matches the current version and closes it
--   merge_key = NULL    -> never matches, so it inserts the new version
-- A new loan has no current version, so its single row falls through to INSERT.
-- "Changed" is decided from the stream itself (old image vs new image), not by joining the
-- history table, so the source never reads the table this statement is modifying.
MERGE INTO CORE.LOAN_ACCOUNT_HISTORY h
USING (
  SELECT c.loan_id AS merge_key, c.loan_id, c.customer_id, c.state, c.balance, c.apr, c.status,
         c.is_closed, c.hashdiff, c.event_ts
  FROM CORE.LOAN_ACCOUNTS_STREAM c
  WHERE c.METADATA$ACTION = 'INSERT'
  UNION ALL
  SELECT NULL AS merge_key, c.loan_id, c.customer_id, c.state, c.balance, c.apr, c.status,
         c.is_closed, c.hashdiff, c.event_ts
  FROM CORE.LOAN_ACCOUNTS_STREAM c
  JOIN CORE.LOAN_ACCOUNTS_STREAM old
    ON old.loan_id = c.loan_id AND old.METADATA$ACTION = 'DELETE' AND old.hashdiff <> c.hashdiff
  WHERE c.METADATA$ACTION = 'INSERT'
) s
ON h.loan_id = s.merge_key AND h.is_current
WHEN MATCHED AND h.hashdiff <> s.hashdiff THEN UPDATE SET
  valid_to   = s.event_ts,
  is_current = FALSE
WHEN NOT MATCHED THEN INSERT
  (loan_id, customer_id, state, balance, apr, status, is_closed, hashdiff, valid_from, valid_to, is_current)
VALUES
  (s.loan_id, s.customer_id, s.state, s.balance, s.apr, s.status, s.is_closed, s.hashdiff, s.event_ts, NULL, TRUE);

CREATE OR REPLACE TASK MART.T_DAILY_COLLECTIONS
  USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
  USER_TASK_TIMEOUT_MS = 600000
  AFTER CORE.T_LOAD_PAYMENTS
AS
-- Recompute only the dates that received new payments (including late-arriving ones),
-- instead of rebuilding the whole mart.
MERGE INTO MART.DAILY_COLLECTIONS d
USING (
  SELECT
    paid_date,
    COUNT(*)                     AS payments,
    SUM(amount)                  AS amount_collected,
    COUNT_IF(days_late > 0)      AS late_payments,
    ROUND(AVG(days_late), 2)     AS avg_days_late
  FROM CORE.PAYMENTS
  WHERE paid_date IN (SELECT DISTINCT paid_date FROM CORE.PAYMENTS_STREAM)
  GROUP BY paid_date
) s
ON d.paid_date = s.paid_date
WHEN MATCHED THEN UPDATE SET
  payments         = s.payments,
  amount_collected = s.amount_collected,
  late_payments    = s.late_payments,
  avg_days_late    = s.avg_days_late,
  refreshed_at     = CURRENT_TIMESTAMP()::TIMESTAMP_NTZ
WHEN NOT MATCHED THEN INSERT
  (paid_date, payments, amount_collected, late_payments, avg_days_late, refreshed_at)
VALUES
  (s.paid_date, s.payments, s.amount_collected, s.late_payments, s.avg_days_late, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ);

-- Resume children first, then the root (only a resumed root starts runs).
ALTER TASK MART.T_DAILY_COLLECTIONS RESUME;
ALTER TASK CORE.T_LOAN_HISTORY RESUME;
ALTER TASK CORE.T_LOAD_PAYMENTS RESUME;
ALTER TASK CORE.T_LOAD_ACCOUNTS RESUME;
ALTER TASK CORE.T_REJECT_EVENTS RESUME;
